acceptance.command:
: "${BASE:?Set BASE to the recorded API implementation base}"
ALLOWED='src/config-admin.test.ts
src/config-fs.test.ts
src/config-fs.ts
src/config-write.audit.test.ts
src/config-write.crash.test.ts
src/config-write.ts'
scope_check() {
  local changed extra
  changed=$(git diff --no-renames --name-only "$BASE" HEAD) || return 1
  extra=$(printf '%s\n' "$changed" | grep -vxF "$ALLOWED" || true)
  [ -z "$extra" ] || { echo "outside allow-list: $extra"; return 1; }
  [ -z "$(git diff --name-only --cached)" ] || { echo "staged changes"; return 1; }
  [ -z "$(git diff --name-only)" ] || { echo "unstaged changes"; return 1; }
  [ -z "$(git status --porcelain)" ] || { echo "status not clean"; return 1; }
  git diff --exit-code "$BASE" HEAD -- . ':(exclude)src/config-admin.test.ts' ':(exclude)src/config-fs.test.ts' ':(exclude)src/config-fs.ts' ':(exclude)src/config-write.audit.test.ts' ':(exclude)src/config-write.crash.test.ts' ':(exclude)src/config-write.ts' || return 1
}
scope_check
